function useSeo(title: string, description: string) {
  useEffect(() => {
    document.title = `${title} · KASNEB Learning Hub`;
    let meta = document.querySelector('meta[name="description"]');
    if (!meta) { meta = document.createElement('meta'); meta.setAttribute('name', 'description'); document.head.appendChild(meta); }
    meta.setAttribute('content', description);
  }, [title, description]);
}

function formatKES(amount: number) { return `KES ${amount.toLocaleString('en-KE')}`; }
function initials(name: string) { return name.split(' ').map((part) => part[0]).join('').slice(0, 2); }

function Skeleton({ className = '' }: { className?: string }) {
  return <div className={`animate-pulse rounded-lg bg-foreground/10 ${className}`} />;
}

function QueryNotice({ message, onRetry }: { message: string; onRetry?: () => void }) {
  return <div className="rounded-2xl border border-accent/30 bg-accent/10 p-5 flex items-start gap-3 text-sm">
    <CircleAlert className="h-5 w-5 shrink-0 text-accent" />
    <div className="flex-1"><p className="font-semibold">{message}</p><p className="mt-1 text-muted-foreground">Showing the latest saved study plan while we reconnect.</p></div>
    {onRetry && <button data-testid="button-retry-query" onClick={onRetry} className="inline-flex items-center gap-2 text-sm font-semibold text-primary hover:text-accent"><RefreshCw className="h-4 w-4" />Retry</button>}
  </div>;
}

