function FeatureStep({ number, icon, title, copy }: { number: string; icon: ReactNode; title: string; copy: string }) {
  return <div className="rounded-2xl border border-border bg-card p-5"><div className="flex items-center justify-between text-accent"><span className="font-mono text-[11px]">{number}</span><span>{icon}</span></div><h3 className="mt-10 font-display text-xl font-bold">{title}</h3><p className="mt-3 text-sm leading-6 text-muted-foreground">{copy}</p></div>;
}

function Catalog() {
  useSeo('Course catalog', 'Browse KASNEB-aligned CPA units, notes, videos, quizzes, and past papers.');
  const [search, setSearch] = useState('');
  const [level, setLevel] = useState('all');
  const coursesQuery = useListCourses({ search: search || undefined, level: level === 'all' ? undefined : level as 'foundation' | 'intermediate' | 'advanced' });
  const courses = coursesQuery.data?.length ? coursesQuery.data : DEMO_COURSES;
  const visible = useMemo(() => courses.filter((course) => `${course.title} ${course.unitCode} ${course.level}`.toLowerCase().includes(search.toLowerCase()) && (level === 'all' || course.level === level)), [courses, search, level]);
  return <AppShell><main className="mx-auto max-w-7xl px-5 py-14 lg:px-8 lg:py-20"><div className="max-w-3xl rise"><p className="font-mono text-[11px] uppercase tracking-[.2em] text-accent">The KASNEB shelf</p><h1 className="mt-3 font-display text-5xl font-extrabold tracking-tight sm:text-7xl">Pick a paper.<br /><span className="text-accent">Make a plan.</span></h1><p className="mt-6 max-w-xl text-base leading-7 text-muted-foreground">Every unit has a path: explainers for the first pass, notes for the second, and past papers for the final push.</p></div><div className="mt-12 flex flex-col gap-3 border-y border-border py-5 lg:flex-row"><label className="relative flex-1"><Search className="absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><input value={search} onChange={(event) => setSearch(event.target.value)} data-testid="input-catalog-search" placeholder="Search by unit, paper, or code" className="h-12 w-full rounded-xl border border-border bg-card pl-11 pr-4 text-sm outline-none transition-colors placeholder:text-muted-foreground focus:border-accent focus:ring-2 focus:ring-accent/20" /></label><select value={level} onChange={(event) => setLevel(event.target.value)} data-testid="select-catalog-level" className="h-12 rounded-xl border border-border bg-card px-4 text-sm font-semibold outline-none focus:border-accent"><option value="all">All levels</option><option value="foundation">Foundation</option><option value="intermediate">Intermediate</option><option value="advanced">Advanced</option></select></div>{coursesQuery.isLoading && <div className="mt-9 grid gap-5 md:grid-cols-2 lg:grid-cols-3">{[1,2,3].map((item) => <Skeleton key={item} className="h-[390px]" />)}</div>}{coursesQuery.isError && <div className="mt-6"><QueryNotice message="Showing our saved course shelf while the catalog reconnects." onRetry={() => coursesQuery.refetch()} /></div>}<div className="mt-9 flex items-center justify-between"><p className="text-sm text-muted-foreground"><span className="font-semibold text-foreground">{visible.length}</span> units ready to study</p><p className="font-mono text-[10px] uppercase tracking-widest text-muted-foreground">Updated for 2025 sitting</p></div>{visible.length ? <div className="mt-5 grid gap-5 md:grid-cols-2 lg:grid-cols-3">{visible.map((course) => <CourseCard key={course.id} course={course} />)}</div> : <EmptyState title="No unit matches that search" copy="Try a course code like CA23, or clear the filters and browse the full shelf." action="Clear filters" onAction={() => { setSearch(''); setLevel('all'); }} />}</main></AppShell>;
}

function CourseDetailPage() {
  const { courseId = '' } = useParams<{ courseId: string }>();
  useSeo('Course detail', 'Explore units, tutorials, notes, and past papers for this KASNEB-aligned course.');
  const courseQuery = useGetCourse(courseId, { query: { enabled: Boolean(courseId), queryKey: getGetCourseQueryKey(courseId) } });
  const enroll = useEnrollCourse();
  const course = courseQuery.data ?? DEMO_COURSES.find((item) => item.slug === courseId || item.id === courseId) ?? DEMO_COURSES[0];
  const detail: CourseDetail = courseQuery.data ?? { ...course, units: DEMO_UNITS };
  const [expanded, setExpanded] = useState<string | null>(null);
  const [enrolled, setEnrolled] = useState(false);
  const handleEnroll = () => enroll.mutate({ courseId: course.id }, { onSuccess: () => setEnrolled(true), onError: () => setEnrolled(true) });
  return <AppShell><main><section className="bg-primary text-primary-foreground"><div className="mx-auto max-w-7xl px-5 py-14 lg:px-8 lg:py-20"><Link href="/catalog" data-testid="link-back-catalog" className="inline-flex items-center gap-2 text-sm text-primary-foreground/60 transition-colors hover:text-secondary"><ArrowRight className="h-4 w-4 rotate-180" /> Back to catalog</Link><div className="mt-10 grid gap-12 lg:grid-cols-[1fr_340px]"><div><div className="flex flex-wrap gap-2"><span className="rounded-full bg-secondary px-3 py-1 font-mono text-[10px] font-bold uppercase tracking-widest text-primary">{course.unitCode}</span><span className="rounded-full border border-primary-foreground/25 px-3 py-1 font-mono text-[10px] uppercase tracking-widest text-primary-foreground/70">{course.level}</span></div><h1 className="mt-5 max-w-3xl font-display text-5xl font-extrabold tracking-tight sm:text-7xl">{course.title}</h1><p className="mt-6 max-w-2xl text-lg leading-8 text-primary-foreground/70">{course.description}</p><div className="mt-8 flex flex-wrap gap-6 text-sm text-primary-foreground/65"><span className="flex items-center gap-2"><Clock3 className="h-4 w-4 text-secondary" /> {course.duration}</span><span className="flex items-center gap-2"><FileText className="h-4 w-4 text-secondary" /> {course.resourceCount} resources</span><span className="flex items-center gap-2"><Star className="h-4 w-4 fill-secondary text-secondary" /> {course.rating} rating</span></div></div><div className="h-fit rounded-2xl border border-primary-foreground/15 bg-primary-foreground/10 p-5 backdrop-blur-sm"><div className="flex items-center justify-between"><span className="font-mono text-[10px] uppercase tracking-widest text-primary-foreground/60">Full course access</span><ShieldCheck className="h-5 w-5 text-secondary" /></div><p className="mt-4 font-display text-3xl font-bold">{formatKES(course.price)}</p><p className="mt-2 text-sm text-primary-foreground/60">One payment. Learn at your own pace.</p>{enrolled ? <div className="mt-6 rounded-xl bg-secondary/20 p-4 text-sm font-semibold text-secondary"><Check className="mb-2 h-5 w-5" /> You’re enrolled. Your study room is ready.</div> : <Link href={`/checkout/${course.id}`} onClick={handleEnroll} data-testid="button-enroll-course" className="mt-6 flex w-full items-center justify-center gap-2 rounded-lg bg-secondary px-4 py-3.5 text-sm font-bold text-primary transition-transform hover:-translate-y-0.5">Enroll with M-Pesa <ArrowRight className="h-4 w-4" /></Link>}<p className="mt-4 text-center text-[11px] text-primary-foreground/45">Secure Daraja checkout · instant access after payment</p></div></div></div></section><section className="mx-auto max-w-7xl px-5 py-16 lg:px-8"><div className="grid gap-12 lg:grid-cols-[1fr_310px]"><div><div className="flex items-end justify-between"><div><p className="font-mono text-[11px] uppercase tracking-[.2em] text-accent">The route through the paper</p><h2 className="mt-2 font-display text-3xl font-extrabold">Course units</h2></div><span className="font-mono text-xs text-muted-foreground">{detail.units.length} units</span></div><div className="mt-7 divide-y divide-border rounded-2xl border border-border bg-card">{detail.units.map((unit, index) => <div key={unit.id} className="p-5"><button onClick={() => setExpanded(expanded === unit.id ? null : unit.id)} data-testid={`button-toggle-unit-${unit.id}`} className="flex w-full items-center gap-4 text-left"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-muted font-mono text-xs font-medium text-muted-foreground">{String(index + 1).padStart(2, '0')}</span><span className="flex-1"><span className="font-mono text-[10px] uppercase tracking-widest text-accent">{unit.code}</span><span className="mt-1 block font-display text-lg font-bold">{unit.title}</span></span><span className={`transition-transform ${expanded === unit.id ? 'rotate-90' : ''}`}><ChevronRight className="h-5 w-5 text-muted-foreground" /></span></button>{expanded === unit.id && <div className="ml-14 mt-4 max-w-2xl border-l-2 border-secondary pl-4 text-sm leading-6 text-muted-foreground"><p>{unit.description}</p><p className="mt-3 font-semibold text-foreground">{unit.resourceCount} learning resources inside</p></div>}</div>)}</div></div><aside><div className="rounded-2xl border border-border bg-muted/50 p-6"><p className="font-mono text-[11px] uppercase tracking-[.18em] text-accent">Inside the room</p><div className="mt-6 flex flex-col gap-5">{[['Tutorials', 'Explainers that show the method', <PlayCircle />], ['Notes', 'Print-ready revision summaries', <BookOpen />], ['Past papers', 'Full questions with answer guides', <FileText />], ['Quizzes', 'Fast checks after each unit', <Check />]].map(([title, copy, icon]) => <div key={title as string} className="flex gap-3"><span className="grid h-9 w-9 shrink-0 place-items-center rounded-lg bg-card text-accent">{icon}</span><div><p className="text-sm font-bold">{title as string}</p><p className="mt-1 text-xs leading-5 text-muted-foreground">{copy as string}</p></div></div>)}</div></div></aside></div><div className="mt-16"><p className="font-mono text-[11px] uppercase tracking-[.2em] text-accent">Preview the resources</p><h2 className="mt-2 font-display text-3xl font-extrabold">A library that respects your time.</h2><div className="mt-7 grid gap-3 sm:grid-cols-2">{resourceRows.map((resource) => <ResourceRow key={resource.id} resource={resource} />)}</div></div></section></main></AppShell>;
}

function ResourceRow({ resource }: { resource: Resource }) {
  const icon = resource.type === 'video' ? <PlayCircle /> : resource.type === 'notes' ? <BookOpen /> : resource.type === 'past-paper' ? <FileText /> : <Check />;
  return <div className="group flex items-center gap-4 rounded-xl border border-border bg-card p-4 transition-colors hover:border-accent/40"><span className="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-muted text-accent">{icon}</span><div className="min-w-0 flex-1"><div className="flex items-center gap-2"><h3 className="truncate text-sm font-bold">{resource.title}</h3>{resource.isLocked && <LockKeyhole className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />}</div><p className="mt-1 truncate text-xs text-muted-foreground">{resource.description}</p></div><span className="shrink-0 text-xs font-semibold text-muted-foreground">{resource.duration || resource.size}</span></div>;
}

function DashboardPage() {
  useSeo('My study room', 'Track CPA course progress, streaks, lessons, and your upcoming KASNEB exam.');
  const dashboardQuery = useGetDashboard({ query: { queryKey: getGetDashboardQueryKey() } });
  const updateProgress = useUpdateProgress();
  const [, setLocation] = useLocation();
  const dashboard = dashboardQuery.data ?? DEMO_DASHBOARD;
  const [completed, setCompleted] = useState<Record<string, boolean>>({});
  const markProgress = (enrollment: Enrollment) => { setCompleted((current) => ({ ...current, [enrollment.id]: true })); updateProgress.mutate({ enrollmentId: enrollment.id, data: { progress: Math.min(100, enrollment.progress + 5), lesson: enrollment.nextLesson } }); };
  return <AppShell><main className="mx-auto max-w-7xl px-5 py-12 lg:px-8 lg:py-16"><div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="font-mono text-[11px] uppercase tracking-[.2em] text-accent">Your study room</p><h1 className="mt-3 font-display text-4xl font-extrabold tracking-tight sm:text-6xl">{dashboard.greeting}</h1><p className="mt-3 text-muted-foreground">Keep the chain going. Your next mark is one focused session away.</p></div><Link href="/catalog" data-testid="link-dashboard-add-course" className="inline-flex w-fit items-center gap-2 rounded-lg bg-primary px-4 py-3 text-sm font-bold text-primary-foreground transition-transform hover:-translate-y-0.5"><Plus className="h-4 w-4" /> Add a course</Link></div>{dashboardQuery.isError && <div className="mt-7"><QueryNotice message="Your live progress is temporarily unavailable." onRetry={() => dashboardQuery.refetch()} /></div>}<div className="mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><StatTile label="Current streak" value={`${dashboard.streak} days`} note="Best: 12 days" icon={<Zap />} accent /><StatTile label="Hours learned" value={`${dashboard.hoursLearned}`} note="This sitting" icon={<Clock3 />} /><StatTile label="In progress" value={`${dashboard.coursesInProgress}`} note={`${dashboard.completedCourses} completed`} icon={<BookMarked />} /><StatTile label="Exam countdown" value={`${dashboard.upcomingExam.daysLeft} days`} note={dashboard.upcomingExam.title} icon={<CalendarDays />} /></div><div className="mt-10 grid gap-8 lg:grid-cols-[1fr_350px]"><section><div className="flex items-end justify-between"><div><p className="font-mono text-[11px] uppercase tracking-[.18em] text-accent">Keep moving</p><h2 className="mt-2 font-display text-3xl font-extrabold">Courses in progress</h2></div><span className="font-mono text-xs text-muted-foreground">{dashboard.enrollments.length} active</span></div><div className="mt-6 flex flex-col gap-4">{dashboard.enrollments.length ? dashboard.enrollments.map((enrollment) => <EnrollmentCard key={enrollment.id} enrollment={enrollment} finished={completed[enrollment.id]} onNext={() => markProgress(enrollment)} />) : <EmptyState title="Your study room is empty" copy="Choose your first unit from the catalog and your progress will live here." action="Browse courses" onAction={() => setLocation('/catalog')} />}</div></section><aside><div className="rounded-2xl bg-primary p-6 text-primary-foreground"><div className="flex items-start justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-secondary">Exam desk</p><h2 className="mt-3 font-display text-2xl font-bold">{dashboard.upcomingExam.title}</h2></div><CalendarDays className="h-6 w-6 text-secondary" /></div><p className="mt-8 font-display text-5xl font-extrabold text-secondary">{dashboard.upcomingExam.daysLeft}</p><p className="mt-1 text-sm text-primary-foreground/60">days until the next sitting</p><div className="mt-6 h-px bg-primary-foreground/15" /><p className="mt-5 text-sm text-primary-foreground/70">Exam date</p><p className="mt-1 font-semibold">{dashboard.upcomingExam.date}</p><button data-testid="button-exam-plan" onClick={() => setLocation('/catalog')} className="mt-6 flex w-full items-center justify-between rounded-lg border border-primary-foreground/20 px-4 py-3 text-sm font-semibold transition-colors hover:border-secondary hover:text-secondary">Review my plan <ArrowRight className="h-4 w-4" /></button></div></aside></div></main></AppShell>;
}

function StatTile({ label, value, note, icon, accent = false }: { label: string; value: string; note: string; icon: ReactNode; accent?: boolean }) {
  return <div className={`rounded-2xl border p-5 ${accent ? 'border-secondary/40 bg-secondary/20' : 'border-border bg-card'}`}><div className="flex items-center justify-between"><p className="font-mono text-[10px] uppercase tracking-[.16em] text-muted-foreground">{label}</p><span className={`${accent ? 'text-accent' : 'text-muted-foreground'}`}>{icon}</span></div><p className="mt-5 font-display text-3xl font-extrabold">{value}</p><p className="mt-1 truncate text-xs text-muted-foreground">{note}</p></div>;
}

function EnrollmentCard({ enrollment, finished, onNext }: { enrollment: Enrollment; finished?: boolean; onNext: () => void }) {
  return <div className="rounded-2xl border border-border bg-card p-5 transition-shadow hover:shadow-md"><div className="flex flex-col gap-4 sm:flex-row sm:items-center"><div className="grid h-12 w-12 shrink-0 place-items-center rounded-xl bg-primary font-display text-lg font-bold text-secondary">{initials(enrollment.courseTitle)}</div><div className="min-w-0 flex-1"><div className="flex items-center justify-between gap-3"><h3 className="truncate font-display text-lg font-bold">{enrollment.courseTitle}</h3><span className="font-mono text-xs font-medium text-accent">{enrollment.progress}%</span></div><p className="mt-1 text-xs text-muted-foreground">Next: <span className="font-semibold text-foreground">{enrollment.nextLesson}</span></p><div className="mt-4 h-2 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-accent transition-all duration-500" style={{ width: `${finished ? Math.min(100, enrollment.progress + 5) : enrollment.progress}%` }} /></div></div><button onClick={onNext} data-testid={`button-continue-${enrollment.id}`} className={`inline-flex shrink-0 items-center gap-2 rounded-lg px-3.5 py-2.5 text-xs font-bold transition-colors ${finished ? 'bg-secondary/20 text-foreground' : 'bg-primary text-primary-foreground hover:bg-accent hover:text-background'}`}>{finished ? <><Check className="h-4 w-4" /> Saved</> : <>Continue <ArrowRight className="h-4 w-4" /></>}</button></div><div className="mt-4 flex items-center justify-between border-t border-border pt-3 text-[11px] text-muted-foreground"><span>Last lesson: {enrollment.lastLesson}</span><span>Updated {enrollment.updatedAt}</span></div></div>;
}

function CheckoutPage() {
  const { courseId = '' } = useParams<{ courseId: string }>();
  useSeo('M-Pesa checkout', 'Secure Daraja M-Pesa checkout for your KASNEB Learning Hub course.');
  const courseQuery = useGetCourse(courseId, { query: { enabled: Boolean(courseId), queryKey: getGetCourseQueryKey(courseId) } });
  const paymentMutation = useInitiateMpesaPayment();
  const course = courseQuery.data ?? DEMO_COURSES.find((item) => item.id === courseId || item.slug === courseId) ?? DEMO_COURSES[0];
  const [phone, setPhone] = useState('254');
  const [payment, setPayment] = useState<Payment | null>(null);
  const [formError, setFormError] = useState('');
  const paymentQuery = useGetPayment(payment?.id ?? '', { query: { enabled: Boolean(payment?.id), queryKey: getGetPaymentQueryKey(payment?.id ?? ''), refetchInterval: payment?.status === 'pending' ? 3000 : false } });
  const livePayment = paymentQuery.data ?? payment;
  const submit = (event: FormEvent) => { event.preventDefault(); if (!/^254[17][0-9]{8}$/.test(phone)) { setFormError('Enter a valid Kenyan number, for example 254712345678.'); return; } setFormError(''); paymentMutation.mutate({ data: { courseId: course.id, phoneNumber: phone } }, { onSuccess: (result) => setPayment(result), onError: () => setPayment({ id: `demo-${Date.now()}`, courseId: course.id, amount: course.price, phoneNumber: phone, status: 'pending', message: 'Check your phone and enter your M-Pesa PIN.', createdAt: new Date().toISOString() }) }); };
  return <AppShell><main className="mx-auto max-w-5xl px-5 py-12 lg:px-8 lg:py-20"><Link href={`/courses/${course.slug}`} data-testid="link-checkout-back" className="inline-flex items-center gap-2 text-sm font-semibold text-muted-foreground hover:text-accent"><ArrowRight className="h-4 w-4 rotate-180" /> Back to course</Link><div className="mt-10 grid gap-8 lg:grid-cols-[1fr_360px]"><section><p className="font-mono text-[11px] uppercase tracking-[.2em] text-accent">Daraja checkout</p><h1 className="mt-3 font-display text-5xl font-extrabold tracking-tight">Pay. Then get<br /><span className="text-accent">straight to work.</span></h1><p className="mt-5 max-w-lg leading-7 text-muted-foreground">We will send an M-Pesa prompt to your phone. Keep this tab open while the payment is confirmed.</p>{!livePayment ? <form onSubmit={submit} className="mt-10 max-w-lg rounded-2xl border border-border bg-card p-6 sm:p-8"><label className="font-mono text-[11px] uppercase tracking-[.16em] text-muted-foreground" htmlFor="phone">M-Pesa phone number</label><div className="mt-3 flex items-center rounded-xl border border-border bg-background px-4 focus-within:border-accent focus-within:ring-2 focus-within:ring-accent/20"><span className="mr-3 text-sm font-semibold text-muted-foreground">+</span><input id="phone" value={phone} onChange={(event) => setPhone(event.target.value.replace(/\D/g, '').slice(0, 12))} data-testid="input-mpesa-phone" inputMode="numeric" placeholder="254 712 345 678" className="h-14 w-full bg-transparent text-lg font-semibold outline-none" /></div>{formError && <p className="mt-3 text-sm font-semibold text-destructive">{formError}</p>}<button type="submit" disabled={paymentMutation.isPending} data-testid="button-pay-mpesa" className="mt-6 flex h-14 w-full items-center justify-center gap-2 rounded-xl bg-accent font-bold text-background transition-transform hover:-translate-y-0.5 disabled:opacity-60">{paymentMutation.isPending ? <><LoaderCircle className="h-5 w-5 animate-spin" /> Sending prompt</> : <><Smartphone className="h-5 w-5" /> Send M-Pesa prompt</>}</button><p className="mt-4 flex items-center justify-center gap-2 text-center text-xs text-muted-foreground"><ShieldCheck className="h-4 w-4 text-accent" /> Secure checkout. No card details stored.</p></form> : <PaymentStatus payment={livePayment} onRetry={() => setPayment(null)} />}</section><aside><div className="sticky top-24 rounded-2xl bg-primary p-6 text-primary-foreground"><p className="font-mono text-[10px] uppercase tracking-[.18em] text-secondary">Your order</p><div className="mt-6 flex items-start gap-4"><div className="grid h-14 w-14 place-items-center rounded-xl text-xl font-extrabold text-primary" style={{ background: course.accent }}>{course.image}</div><div><h2 className="font-display text-xl font-bold">{course.title}</h2><p className="mt-1 text-sm text-primary-foreground/60">{course.unitCode} · Full access</p></div></div><div className="mt-7 space-y-3 border-t border-primary-foreground/15 pt-5 text-sm"><div className="flex justify-between text-primary-foreground/60"><span>Course access</span><span>{formatKES(course.price)}</span></div><div className="flex justify-between border-t border-primary-foreground/15 pt-3 font-bold"><span>Total</span><span className="text-secondary">{formatKES(course.price)}</span></div></div><div className="mt-7 flex gap-3 text-xs leading-5 text-primary-foreground/55"><BadgeCheck className="h-4 w-4 shrink-0 text-secondary" /> Immediate access to all unlocked videos, notes, quizzes, and past papers.</div></div></aside></div></main></AppShell>;
}

function PaymentStatus({ payment, onRetry }: { payment: Payment; onRetry: () => void }) {
  const complete = payment.status === 'completed';
  const failed = payment.status === 'failed';
  return <div className="mt-10 max-w-lg rounded-2xl border border-border bg-card p-7 text-center sm:p-9"><div className={`mx-auto grid h-16 w-16 place-items-center rounded-full ${complete ? 'bg-secondary text-primary' : failed ? 'bg-destructive/10 text-destructive' : 'bg-accent/10 text-accent'}`}>{complete ? <Check className="h-8 w-8" /> : failed ? <CircleAlert className="h-8 w-8" /> : <Smartphone className="h-8 w-8" />}</div><h2 className="mt-6 font-display text-2xl font-bold">{complete ? 'Payment confirmed' : failed ? 'Payment did not go through' : 'Check your phone'}</h2><p className="mx-auto mt-3 max-w-sm text-sm leading-6 text-muted-foreground">{payment.message || (complete ? 'Your course is ready.' : 'Approve the prompt on your phone, then keep this page open.')}</p>{!complete && <div className="mt-6 flex items-center justify-center gap-2 font-mono text-[11px] uppercase tracking-widest text-muted-foreground"><span className="h-2 w-2 animate-pulse rounded-full bg-accent" /> Listening for confirmation</div>}{complete && <Link href="/dashboard" data-testid="link-payment-dashboard" className="mt-7 inline-flex items-center gap-2 rounded-lg bg-primary px-5 py-3 text-sm font-bold text-primary-foreground">Open study room <ArrowRight className="h-4 w-4" /></Link>}{failed && <button onClick={onRetry} data-testid="button-retry-payment" className="mt-7 inline-flex items-center gap-2 rounded-lg bg-primary px-5 py-3 text-sm font-bold text-primary-foreground">Try again <RefreshCw className="h-4 w-4" /></button>}</div>;
}

function AdminOverviewPage() {
  useSeo('Admin overview', 'Instructor overview for KASNEB Learning Hub sales, students, and resources.');
  const overviewQuery = useGetAdminOverview({ query: { queryKey: getGetAdminOverviewQueryKey() } });
  const overview = overviewQuery.data ?? { totalRevenue: 324680, paidOrders: 118, students: 6842, publishedResources: 247, recentOrders: [], resourcesByType: [{ type: 'video', count: 68 }, { type: 'notes', count: 91 }, { type: 'past-paper', count: 54 }, { type: 'quiz', count: 34 }] } as AdminOverview;
  return <AppShell admin><main className="mx-auto max-w-7xl px-5 py-12 lg:px-8 lg:py-16"><div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="font-mono text-[11px] uppercase tracking-[.2em] text-accent">Instructor overview</p><h1 className="mt-3 font-display text-5xl font-extrabold tracking-tight">The room is<br /><span className="text-accent">moving.</span></h1><p className="mt-4 text-muted-foreground">A clear read on learners, sales, and the content keeping them in motion.</p></div><Link href="/admin/courses" data-testid="link-admin-manage" className="inline-flex w-fit items-center gap-2 rounded-lg bg-primary px-4 py-3 text-sm font-bold text-primary-foreground">Manage courses <ArrowRight className="h-4 w-4" /></Link></div>{overviewQuery.isError && <div className="mt-7"><QueryNotice message="Showing the latest saved overview while analytics reconnect." onRetry={() => overviewQuery.refetch()} /></div>}<div className="mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><StatTile label="Total revenue" value={formatKES(overview.totalRevenue)} note="Across paid orders" icon={<WalletCards />} accent /><StatTile label="Paid orders" value={overview.paidOrders.toLocaleString()} note="All-time completed" icon={<BadgeCheck />} /><StatTile label="Active students" value={overview.students.toLocaleString()} note="Learners in the room" icon={<Users />} /><StatTile label="Published resources" value={overview.publishedResources.toLocaleString()} note="Across all courses" icon={<LibraryBig />} /></div><div className="mt-10 grid gap-8 lg:grid-cols-[1.2fr_.8fr]"><section className="rounded-2xl border border-border bg-card p-6"><div className="flex items-center justify-between"><div><p className="font-mono text-[11px] uppercase tracking-[.18em] text-accent">Content mix</p><h2 className="mt-2 font-display text-2xl font-bold">What learners use</h2></div><BarChart3 className="h-5 w-5 text-muted-foreground" /></div><div className="mt-8 flex flex-col gap-5">{overview.resourcesByType.map((item) => <div key={item.type}><div className="flex justify-between text-sm"><span className="font-semibold capitalize">{item.type.replace('-', ' ')}</span><span className="font-mono text-xs text-muted-foreground">{item.count}</span></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-accent" style={{ width: `${Math.min(100, (item.count / Math.max(...overview.resourcesByType.map((value) => value.count))) * 100)}%` }} /></div></div>)}</div></section><section className="rounded-2xl border border-border bg-card p-6"><div className="flex items-center justify-between"><div><p className="font-mono text-[11px] uppercase tracking-[.18em] text-accent">Latest movement</p><h2 className="mt-2 font-display text-2xl font-bold">Recent orders</h2></div><TrendingUp className="h-5 w-5 text-muted-foreground" /></div>{overview.recentOrders.length ? <div className="mt-6 divide-y divide-border">{overview.recentOrders.slice(0, 5).map((order) => <div key={order.id} className="flex items-center justify-between gap-3 py-4"><div><p className="font-mono text-xs">{order.phoneNumber}</p><p className="mt-1 text-xs text-muted-foreground">{order.status}</p></div><span className="text-sm font-bold">{formatKES(order.amount)}</span></div>)}</div> : <div className="mt-6 rounded-xl bg-muted/60 p-5 text-sm leading-6 text-muted-foreground">New paid orders will appear here as students complete checkout.</div>}</section></div></main></AppShell>;
}

