function AdminStudentsPage() {
  useSeo('Manage students', 'Manage KASNEB Learning Hub student accounts and access.');
  const query = useListAdminStudents();
  const updateStatus = useUpdateStudentStatus();
  const [search, setSearch] = useState('');
  const students = (query.data ?? []).filter((student) => `${student.name} ${student.email}`.toLowerCase().includes(search.toLowerCase()));
  const setStatus = (student: Student) => updateStatus.mutate({ studentId: student.id, data: { status: student.status === 'active' ? 'suspended' : 'active' } }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getGetAdminOverviewQueryKey() }) });
  return <AppShell admin><main className="mx-auto max-w-7xl px-5 py-12 lg:px-8 lg:py-16"><AdminHeader eyebrow="People desk" title="Manage students." copy="Review learner activity, control account access, and keep the study room healthy." action={<div className="rounded-xl border border-border bg-card px-4 py-3 text-sm font-semibold">{students.length} visible students</div>} /><div className="mt-10 flex flex-col gap-3 border-y border-border py-5 sm:flex-row"><label className="relative flex-1"><Search className="absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><input value={search} onChange={(event) => setSearch(event.target.value)} data-testid="input-admin-student-search" placeholder="Search by name or email" className="h-12 w-full rounded-xl border border-border bg-card pl-11 pr-4 text-sm outline-none focus:border-accent" /></label><button onClick={() => query.refetch()} data-testid="button-refresh-students" className="inline-flex h-12 items-center justify-center gap-2 rounded-xl border border-border px-4 text-sm font-bold hover:border-accent"><RefreshCw className="h-4 w-4" /> Refresh</button></div><div className="mt-6 overflow-hidden rounded-2xl border border-border bg-card"><div className="hidden grid-cols-[1.4fr_1.2fr_.7fr_.7fr_.8fr] gap-4 border-b border-border bg-muted/50 px-5 py-3 text-[10px] font-bold uppercase tracking-widest text-muted-foreground md:grid"><span>Student</span><span>Activity</span><span>Progress</span><span>Status</span><span>Access</span></div>{query.isLoading ? <div className="p-6"><Skeleton className="h-20" /></div> : students.length ? students.map((student) => <div key={student.id} className="grid gap-4 border-b border-border p-5 last:border-0 md:grid-cols-[1.4fr_1.2fr_.7fr_.7fr_.8fr] md:items-center"><div className="flex items-center gap-3"><div className="grid h-10 w-10 shrink-0 place-items-center rounded-full bg-primary font-display font-bold text-secondary">{initials(student.name)}</div><div><p className="font-semibold">{student.name}</p><p className="text-xs text-muted-foreground">{student.email}</p><p className="mt-1 text-[11px] text-muted-foreground md:hidden">{student.enrolledCourses} courses · {student.lastActive}</p></div></div><div className="hidden text-sm text-muted-foreground md:block"><p>{student.enrolledCourses} courses enrolled</p><p className="mt-1 text-xs">Last active {student.lastActive}</p></div><div><p className="text-sm font-bold">{student.progress}%</p><div className="mt-2 h-1.5 w-full rounded-full bg-muted"><div className="h-full rounded-full bg-accent" style={{ width: `${student.progress}%` }} /></div></div><span className={`w-fit rounded-full px-2.5 py-1 text-[10px] font-bold uppercase tracking-wider ${student.status === 'active' ? 'bg-secondary/25 text-foreground' : 'bg-destructive/10 text-destructive'}`}>{student.status}</span><button onClick={() => setStatus(student)} disabled={updateStatus.isPending} data-testid={`button-toggle-student-${student.id}`} className="inline-flex w-fit items-center gap-2 rounded-lg border border-border px-3 py-2 text-xs font-bold hover:border-accent disabled:opacity-50">{student.status === 'active' ? <><ShieldCheck className="h-3.5 w-3.5" /> Suspend</> : <><UserCheck className="h-3.5 w-3.5" /> Restore access</>}</button></div>) : <EmptyState title="No students found" copy="Try a different name or email address." action="Clear search" onAction={() => setSearch('')} />}</div></main></AppShell>;
}

function AdminPaymentsPage() {
  useSeo('Manage payments', 'Reconcile KASNEB Learning Hub M-Pesa orders and access.');
  const query = useListAdminPayments();
  const updateStatus = useUpdatePaymentStatus();
  const [filter, setFilter] = useState('all');
  const payments = (query.data ?? []).filter((payment) => filter === 'all' || payment.status === filter);
  const setStatus = (payment: AdminPayment, status: 'pending' | 'completed' | 'failed') => updateStatus.mutate({ paymentId: payment.id, data: { status } }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getGetAdminOverviewQueryKey() }); queryClient.invalidateQueries({ queryKey: getGetPaymentQueryKey(payment.id) }); } });
  return <AppShell admin><main className="mx-auto max-w-7xl px-5 py-12 lg:px-8 lg:py-16"><AdminHeader eyebrow="Money desk" title="Reconcile payments." copy="Review every M-Pesa order, correct its status, and keep course access aligned with payment." action={<div className="rounded-xl border border-border bg-card px-4 py-3 text-sm font-semibold">{payments.length} orders</div>} /><div className="mt-10 flex flex-wrap gap-2 border-y border-border py-5">{['all', 'pending', 'completed', 'failed'].map((status) => <button key={status} onClick={() => setFilter(status)} data-testid={`button-payment-filter-${status}`} className={`rounded-lg px-4 py-2 text-xs font-bold capitalize ${filter === status ? 'bg-primary text-primary-foreground' : 'border border-border bg-card hover:border-accent'}`}>{status}</button>)}</div><div className="mt-6 overflow-hidden rounded-2xl border border-border bg-card">{query.isLoading ? <div className="p-6"><Skeleton className="h-20" /></div> : payments.length ? payments.map((payment) => <div key={payment.id} className="grid gap-4 border-b border-border p-5 last:border-0 md:grid-cols-[1.2fr_1.2fr_.8fr_1.1fr] md:items-center"><div><p className="font-semibold">{payment.studentName}</p><p className="mt-1 font-mono text-xs text-muted-foreground">{payment.phoneNumber}</p></div><div><p className="text-sm font-semibold">{payment.courseTitle}</p><p className="mt-1 text-xs text-muted-foreground">{new Date(payment.createdAt).toLocaleString('en-KE')}</p></div><p className="font-display text-xl font-bold">{formatKES(payment.amount)}</p><div className="flex flex-wrap items-center gap-2"><span className={`rounded-full px-2.5 py-1 text-[10px] font-bold uppercase tracking-wider ${payment.status === 'completed' ? 'bg-secondary/25' : payment.status === 'failed' ? 'bg-destructive/10 text-destructive' : 'bg-accent/15 text-accent'}`}>{payment.status}</span><select value={payment.status} onChange={(event) => setStatus(payment, event.target.value as 'pending' | 'completed' | 'failed')} disabled={updateStatus.isPending} data-testid={`select-payment-status-${payment.id}`} className="h-9 rounded-lg border border-border bg-background px-2 text-xs font-semibold outline-none focus:border-accent"><option value="pending">Pending</option><option value="completed">Completed</option><option value="failed">Failed</option></select></div></div>) : <EmptyState title="No payments in this view" copy="Try another status filter." action="Show all payments" onAction={() => setFilter('all')} />}</div></main></AppShell>;
}

function AdminSupportPage() {
  useSeo('Manage support', 'Manage student support messages for KASNEB Learning Hub.');
  const query = useListAdminMessages();
  const updateStatus = useUpdateMessageStatus();
  const messages = query.data ?? [];
  return <AppShell admin><main className="mx-auto max-w-7xl px-5 py-12 lg:px-8 lg:py-16"><AdminHeader eyebrow="Support desk" title="Stay close to learners." copy="Read incoming questions, mark replies, and keep every student request visible until it is resolved." action={<div className="rounded-xl border border-border bg-card px-4 py-3 text-sm font-semibold">{messages.filter((message) => message.status === 'received').length} need attention</div>} /><div className="mt-10 flex flex-col gap-4">{query.isLoading ? <Skeleton className="h-28" /> : messages.length ? messages.map((message: ContactMessage) => <div key={message.id} className="rounded-2xl border border-border bg-card p-5 sm:p-6"><div className="flex flex-col justify-between gap-4 sm:flex-row"><div><div className="flex flex-wrap items-center gap-2"><h2 className="font-display text-xl font-bold">{message.subject}</h2><span className={`rounded-full px-2.5 py-1 text-[10px] font-bold uppercase tracking-wider ${message.status === 'replied' ? 'bg-secondary/25' : 'bg-accent/15 text-accent'}`}>{message.status}</span></div><p className="mt-2 text-sm text-muted-foreground">{message.name} · {message.email}</p></div><button onClick={() => updateStatus.mutate({ messageId: message.id, data: { status: message.status === 'received' ? 'replied' : 'received' } })} disabled={updateStatus.isPending} data-testid={`button-toggle-message-${message.id}`} className="inline-flex h-10 items-center justify-center gap-2 rounded-lg border border-border px-3 text-xs font-bold hover:border-accent disabled:opacity-50">{message.status === 'received' ? <><Check className="h-4 w-4" /> Mark replied</> : <><RefreshCw className="h-4 w-4" /> Reopen</>}</button></div><p className="mt-5 max-w-3xl text-sm leading-7 text-muted-foreground">{message.message}</p></div>) : <EmptyState title="Your support inbox is clear" copy="New messages from the contact page will appear here." action="Refresh inbox" onAction={() => query.refetch()} />}</div></main></AppShell>;
}

