function AdminSettingsPage() {
  useSeo('Platform settings', 'Manage KASNEB Learning Hub site, enrollment, and support settings.');
  const query = useGetAdminSettings({ query: { queryKey: getGetAdminSettingsQueryKey() } });
  const updateSettings = useUpdateAdminSettings();
  const [form, setForm] = useState<PlatformSettings>(DEFAULT_SETTINGS);
  const [notice, setNotice] = useState('');
  useEffect(() => { if (query.data) setForm(query.data); }, [query.data]);
  const save = (event: FormEvent) => { event.preventDefault(); updateSettings.mutate({ data: form }, { onSuccess: (settings) => { setForm(settings); setNotice('Platform settings saved.'); }, onError: () => setNotice('Settings could not be saved. Try again.') }); };
  return <AppShell admin><main className="mx-auto max-w-4xl px-5 py-12 lg:px-8 lg:py-16"><AdminHeader eyebrow="Control room" title="Set the rules." copy="Update the public identity, support details, enrollment policy, and the exam sitting shown across the platform." action={<Settings className="h-8 w-8 text-accent" />} />{notice && <div className="mt-7 flex items-center gap-3 rounded-xl border border-secondary/40 bg-secondary/20 p-4 text-sm font-semibold"><Check className="h-5 w-5 text-accent" />{notice}</div>}<form onSubmit={save} className="mt-10 grid gap-8"><section className="rounded-2xl border border-border bg-card p-6 sm:p-8"><div><p className="font-mono text-[11px] uppercase tracking-[.18em] text-accent">Public identity</p><h2 className="mt-2 font-display text-2xl font-bold">How the site presents itself</h2></div><div className="mt-7 grid gap-5 sm:grid-cols-2"><TextField label="Site name" value={form.siteName} onChange={(value) => setForm({ ...form, siteName: value })} testId="input-settings-site-name" required /><TextField label="Default currency" value={form.defaultCurrency} onChange={(value) => setForm({ ...form, defaultCurrency: value })} testId="input-settings-currency" required /><TextField label="Support email" type="email" value={form.supportEmail} onChange={(value) => setForm({ ...form, supportEmail: value })} testId="input-settings-support-email" required /><TextField label="Support phone" value={form.supportPhone} onChange={(value) => setForm({ ...form, supportPhone: value })} testId="input-settings-support-phone" required /><div className="sm:col-span-2"><TextField label="Current exam sitting" value={form.examSitting} onChange={(value) => setForm({ ...form, examSitting: value })} testId="input-settings-exam-sitting" required /></div></div></section><section className="rounded-2xl border border-border bg-card p-6 sm:p-8"><div><p className="font-mono text-[11px] uppercase tracking-[.18em] text-accent">Platform controls</p><h2 className="mt-2 font-display text-2xl font-bold">What learners can do</h2></div><div className="mt-7 grid gap-3">{([['allowNewEnrollments', 'Allow new enrollments', 'Students can buy and join courses.'], ['showFeaturedCourses', 'Show featured courses', 'Display featured units on the home page.'], ['maintenanceMode', 'Maintenance mode', 'Show that the platform is temporarily being updated.']] as const).map(([key, title, copy]) => <label key={key} className="flex cursor-pointer items-start gap-4 rounded-xl border border-border p-4 hover:border-accent/50"><input type="checkbox" checked={form[key]} onChange={(event) => setForm({ ...form, [key]: event.target.checked })} data-testid={`checkbox-settings-${key}`} className="mt-1 h-4 w-4 accent-[hsl(var(--accent))]" /><span><span className="block text-sm font-bold">{title}</span><span className="mt-1 block text-xs leading-5 text-muted-foreground">{copy}</span></span></label>)}</div></section><button type="submit" disabled={updateSettings.isPending} data-testid="button-save-settings" className="inline-flex h-12 items-center justify-center gap-2 rounded-lg bg-primary px-5 text-sm font-bold text-primary-foreground disabled:opacity-60">{updateSettings.isPending ? <LoaderCircle className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />} Save all settings</button></form></main></AppShell>;
}

function AdminGuard({ children }: { children: ReactNode }) {
  const { status } = useAdminAuth();
  const [, setLocation] = useLocation();
  useEffect(() => { if (status === 'signed-out') setLocation('/admin/login'); }, [status, setLocation]);
  if (status === 'loading') return <div className="grid min-h-[60vh] place-items-center"><LoaderCircle className="h-6 w-6 animate-spin text-accent" /></div>;
  if (status !== 'signed-in') return null;
  return <>{children}</>;
}

function AdminLoginPage() {
  useSeo('Admin sign in', 'Sign in to the KASNEB Learning Hub admin control center.');
  const { login, status } = useAdminAuth();
  const [, setLocation] = useLocation();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [submitting, setSubmitting] = useState(false);
  useEffect(() => { if (status === 'signed-in') setLocation('/admin'); }, [status, setLocation]);
  const submit = async (event: FormEvent) => {
    event.preventDefault();
    setError('');
    setSubmitting(true);
    try { await login(email, password); setLocation('/admin'); }
    catch (err) { setError(err instanceof Error ? err.message : 'Sign in failed.'); }
    finally { setSubmitting(false); }
  };
  return <div className="noise grid min-h-[100dvh] place-items-center bg-primary px-5 text-primary-foreground"><div className="w-full max-w-md rounded-2xl border border-secondary/25 bg-background p-8 text-foreground sm:p-10"><Logo /><p className="mt-8 font-mono text-[11px] uppercase tracking-[.2em] text-accent">Admin control center</p><h1 className="mt-2 font-display text-3xl font-extrabold">Sign in to manage the room.</h1><p className="mt-3 text-sm leading-6 text-muted-foreground">This area is restricted to KASNEB Learning Hub admins.</p>{error && <div className="mt-6 flex items-center gap-3 rounded-xl border border-destructive/30 bg-destructive/10 p-4 text-sm font-semibold text-destructive"><CircleAlert className="h-5 w-5 shrink-0" />{error}</div>}<form onSubmit={submit} className="mt-7 grid gap-4"><TextField label="Email" type="email" value={email} onChange={setEmail} testId="input-admin-login-email" required /><TextField label="Password" type="password" value={password} onChange={setPassword} testId="input-admin-login-password" required /><button disabled={submitting} data-testid="button-admin-login" className="mt-2 flex h-12 items-center justify-center gap-2 rounded-lg bg-primary font-bold text-primary-foreground disabled:opacity-60">{submitting ? <LoaderCircle className="h-4 w-4 animate-spin" /> : <LockKeyhole className="h-4 w-4" />} Sign in</button></form><Link href="/" data-testid="link-admin-login-home" className="mt-8 inline-flex items-center gap-2 text-sm font-semibold text-muted-foreground hover:text-accent"><ArrowRight className="h-4 w-4 rotate-180" /> Back to the site</Link></div></div>;
}

function AdminAcceptInvitePage() {
  useSeo('Accept admin invite', 'Set your password to join the KASNEB Learning Hub admin team.');
  const search = useSearch();
  const token = new URLSearchParams(search).get('token') ?? '';
  const [, setLocation] = useLocation();
  const { refresh } = useAdminAuth();
  const [password, setPassword] = useState('');
  const [confirm, setConfirm] = useState('');
  const [error, setError] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const submit = async (event: FormEvent) => {
    event.preventDefault();
    setError('');
    if (password.length < 8) { setError('Password must be at least 8 characters.'); return; }
    if (password !== confirm) { setError('Passwords do not match.'); return; }
    setSubmitting(true);
    try { await acceptAdminInvite(token, password); await refresh(); setLocation('/admin'); }
    catch (err) { setError(err instanceof Error ? err.message : 'Could not accept this invite.'); }
    finally { setSubmitting(false); }
  };
  if (!token) {
    return <div className="noise grid min-h-[100dvh] place-items-center bg-primary px-5 text-primary-foreground"><div className="w-full max-w-md rounded-2xl border border-secondary/25 bg-background p-8 text-center text-foreground"><CircleAlert className="mx-auto h-8 w-8 text-accent" /><h1 className="mt-4 font-display text-2xl font-bold">Missing invite link</h1><p className="mt-2 text-sm text-muted-foreground">Open this page using the full invite link an owner sent you.</p></div></div>;
  }
  return <div className="noise grid min-h-[100dvh] place-items-center bg-primary px-5 text-primary-foreground"><div className="w-full max-w-md rounded-2xl border border-secondary/25 bg-background p-8 text-foreground sm:p-10"><Logo /><p className="mt-8 font-mono text-[11px] uppercase tracking-[.2em] text-accent">You're invited</p><h1 className="mt-2 font-display text-3xl font-extrabold">Set your admin password.</h1><p className="mt-3 text-sm leading-6 text-muted-foreground">Choose a password to activate your admin account.</p>{error && <div className="mt-6 flex items-center gap-3 rounded-xl border border-destructive/30 bg-destructive/10 p-4 text-sm font-semibold text-destructive"><CircleAlert className="h-5 w-5 shrink-0" />{error}</div>}<form onSubmit={submit} className="mt-7 grid gap-4"><TextField label="Password" type="password" value={password} onChange={setPassword} testId="input-accept-invite-password" required /><TextField label="Confirm password" type="password" value={confirm} onChange={setConfirm} testId="input-accept-invite-confirm" required /><button disabled={submitting} data-testid="button-accept-invite" className="mt-2 flex h-12 items-center justify-center gap-2 rounded-lg bg-primary font-bold text-primary-foreground disabled:opacity-60">{submitting ? <LoaderCircle className="h-4 w-4 animate-spin" /> : <ShieldCheck className="h-4 w-4" />} Activate account</button></form></div></div>;
}

function AdminTeamPage() {
  useSeo('Team', 'Manage KASNEB Learning Hub admin accounts.');
  const { admin } = useAdminAuth();
  const isOwner = admin?.role === 'owner';
  const query = useQuery({ queryKey: ['admin-accounts'], queryFn: listAdminAccounts, enabled: isOwner });
  const [form, setForm] = useState({ name: '', email: '' });
  const [inviteLink, setInviteLink] = useState('');
  const [error, setError] = useState('');
  const invite = useMutation({
    mutationFn: () => inviteAdmin(form.name, form.email),
    onSuccess: (created) => {
      setInviteLink(`${window.location.origin}/admin/accept-invite?token=${created.inviteToken}`);
      setForm({ name: '', email: '' });
      setError('');
      queryClient.invalidateQueries({ queryKey: ['admin-accounts'] });
    },
    onError: (err) => setError(err instanceof Error ? err.message : 'Could not send invite.'),
  });
  const remove = useMutation({
    mutationFn: (adminId: string) => removeAdminAccount(adminId),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['admin-accounts'] }),
  });
  const submit = (event: FormEvent) => { event.preventDefault(); setInviteLink(''); invite.mutate(); };
  if (!isOwner) {
    return <AppShell admin><main className="mx-auto max-w-3xl px-5 py-16 text-center"><ShieldCheck className="mx-auto h-8 w-8 text-accent" /><h1 className="mt-4 font-display text-3xl font-bold">Owner access only.</h1><p className="mt-2 text-sm text-muted-foreground">Ask the owner admin to invite or manage team accounts.</p></main></AppShell>;
  }
  const accounts = query.data ?? [];
  return <AppShell admin><main className="mx-auto max-w-4xl px-5 py-12 lg:px-8 lg:py-16"><AdminHeader eyebrow="Control room" title="Manage your team." copy="Invite trusted colleagues into the admin control center, and revoke access when someone leaves." action={<Users className="h-8 w-8 text-accent" />} />{inviteLink && <div className="mt-7 rounded-xl border border-secondary/40 bg-secondary/20 p-5 text-sm"><p className="font-bold">Invite ready — share this link directly with them:</p><p className="mt-2 break-all font-mono text-xs">{inviteLink}</p><p className="mt-2 text-xs text-muted-foreground">It expires in 7 days and only works once.</p></div>}{error && <div className="mt-7 flex items-center gap-3 rounded-xl border border-destructive/30 bg-destructive/10 p-4 text-sm font-semibold text-destructive"><CircleAlert className="h-5 w-5 shrink-0" />{error}</div>}<form onSubmit={submit} className="mt-8 grid gap-4 rounded-2xl border border-border bg-card p-6 sm:grid-cols-[1fr_1fr_auto] sm:items-end sm:p-8"><TextField label="Name" value={form.name} onChange={(value) => setForm({ ...form, name: value })} testId="input-invite-name" required /><TextField label="Email" type="email" value={form.email} onChange={(value) => setForm({ ...form, email: value })} testId="input-invite-email" required /><button disabled={invite.isPending} data-testid="button-send-invite" className="flex h-11 items-center justify-center gap-2 rounded-lg bg-primary px-4 text-sm font-bold text-primary-foreground disabled:opacity-60">{invite.isPending ? <LoaderCircle className="h-4 w-4 animate-spin" /> : <Plus className="h-4 w-4" />} Invite</button></form><div className="mt-10 overflow-hidden rounded-2xl border border-border bg-card">{query.isLoading ? <div className="p-6"><Skeleton className="h-20" /></div> : accounts.length ? accounts.map((account) => <div key={account.id} className="flex items-center justify-between gap-4 border-b border-border p-5 last:border-0"><div><p className="font-semibold">{account.name} {account.id === admin.id && <span className="ml-2 text-xs font-normal text-muted-foreground">(you)</span>}</p><p className="text-xs text-muted-foreground">{account.email}</p></div><div className="flex items-center gap-3"><span className={`rounded-full px-2.5 py-1 text-[10px] font-bold uppercase tracking-wider ${account.role === 'owner' ? 'bg-secondary/25' : 'bg-muted'}`}>{account.role}</span><span className={`rounded-full px-2.5 py-1 text-[10px] font-bold uppercase tracking-wider ${account.status === 'active' ? 'bg-secondary/25' : 'bg-accent/15 text-accent'}`}>{account.status}</span>{account.id !== admin.id && <button onClick={() => { if (window.confirm(`Remove ${account.name}?`)) remove.mutate(account.id); }} data-testid={`button-remove-admin-${account.id}`} className="grid h-9 w-9 place-items-center rounded-lg text-muted-foreground transition-colors hover:bg-destructive/10 hover:text-destructive"><Trash2 className="h-4 w-4" /></button>}</div></div>) : <div className="p-8 text-center text-sm text-muted-foreground">No admins yet.</div>}</div></main></AppShell>;
}

function AdminCoursesPage() {
  useSeo('Manage courses', 'Create KASNEB courses and publish learning resources from the instructor console.');
  const coursesQuery = useListCourses();
  const createCourse = useCreateCourse();
  const updateCourse = useUpdateCourse();
  const deleteCourse = useDeleteCourse();
  const createResource = useCreateResource();
  const resourcesQuery = useListAdminResources();
  const deleteResource = useDeleteResource();
  const [selected, setSelected] = useState<Course | null>(null);
  const [showCourseForm, setShowCourseForm] = useState(false);
  const [showResourceForm, setShowResourceForm] = useState(false);
  const [notice, setNotice] = useState('');
  const courses = coursesQuery.data?.length ? coursesQuery.data : DEMO_COURSES;
  const [courseForm, setCourseForm] = useState({ title: '', unitCode: '', level: 'intermediate', price: '3500', duration: '10 weeks', description: '' });
  const [resourceForm, setResourceForm] = useState({ title: '', type: 'video', description: '', duration: '', size: '' });
  const saveCourse = (event: FormEvent) => { event.preventDefault(); const data = { title: courseForm.title, unitCode: courseForm.unitCode, level: courseForm.level as 'foundation' | 'intermediate' | 'advanced', price: Number(courseForm.price), duration: courseForm.duration, description: courseForm.description, featured: false, accent: '#f2b84b' }; if (selected) updateCourse.mutate({ courseId: selected.id, data }, { onSuccess: () => setNotice('Course changes saved.'), onError: () => setNotice('Course draft saved locally. Connect storage to publish it.') }); else createCourse.mutate({ data }, { onSuccess: () => setNotice('Course created successfully.'), onError: () => setNotice('Course draft captured. Connect storage to publish it.') }); setShowCourseForm(false); };
  const saveResource = (event: FormEvent) => { event.preventDefault(); if (!selected) return; createResource.mutate({ data: { courseId: selected.id, title: resourceForm.title, type: resourceForm.type as 'video' | 'notes' | 'past-paper' | 'quiz', description: resourceForm.description, duration: resourceForm.duration, size: resourceForm.size } }, { onSuccess: () => setNotice('Resource published to the course.'), onError: () => setNotice('Resource draft captured. Connect storage to publish it.') }); setShowResourceForm(false); };
  const removeCourse = (course: Course) => { if (!window.confirm(`Delete ${course.title}? Its units and resources will also be removed.`)) return; deleteCourse.mutate({ courseId: course.id }, { onSuccess: () => { setNotice('Course deleted.'); queryClient.invalidateQueries({ queryKey: getListCoursesQueryKey() }); resourcesQuery.refetch(); }, onError: () => setNotice('Course could not be deleted.') }); };
  const removeResource = (resource: AdminResource) => { if (!window.confirm(`Delete ${resource.title}?`)) return; deleteResource.mutate({ resourceId: resource.id }, { onSuccess: () => { setNotice('Resource deleted.'); resourcesQuery.refetch(); queryClient.invalidateQueries({ queryKey: getListCoursesQueryKey() }); }, onError: () => setNotice('Resource could not be deleted.') }); };
  const edit = (course: Course) => { setSelected(course); setCourseForm({ title: course.title, unitCode: course.unitCode, level: course.level, price: String(course.price), duration: course.duration, description: course.description }); setShowCourseForm(true); };
  return <AppShell admin><main className="mx-auto max-w-7xl px-5 py-12 lg:px-8 lg:py-16"><div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="font-mono text-[11px] uppercase tracking-[.2em] text-accent">Content desk</p><h1 className="mt-3 font-display text-5xl font-extrabold tracking-tight">Build the shelf.</h1><p className="mt-4 text-muted-foreground">Shape each unit into a dependable path from first principles to past paper.</p></div><button onClick={() => { setSelected(null); setCourseForm({ title: '', unitCode: '', level: 'intermediate', price: '3500', duration: '10 weeks', description: '' }); setShowCourseForm(true); }} data-testid="button-create-course" className="inline-flex w-fit items-center gap-2 rounded-lg bg-accent px-4 py-3 text-sm font-bold text-background"><Plus className="h-4 w-4" /> New course</button></div>{notice && <div className="mt-7 flex items-center gap-3 rounded-xl border border-secondary/40 bg-secondary/20 p-4 text-sm font-semibold"><Check className="h-5 w-5 text-accent" />{notice}<button className="ml-auto" onClick={() => setNotice('')} data-testid="button-dismiss-notice"><X className="h-4 w-4" /></button></div>}<div className="mt-10 grid gap-8 lg:grid-cols-[1fr_340px]"><section><div className="flex items-center justify-between"><h2 className="font-display text-2xl font-bold">Your courses</h2><span className="font-mono text-xs text-muted-foreground">{courses.length} listed</span></div><div className="mt-5 divide-y divide-border rounded-2xl border border-border bg-card">{courses.map((course) => <div key={course.id} className="flex items-center gap-4 p-5"><div className="grid h-12 w-12 shrink-0 place-items-center rounded-xl font-display font-bold text-primary" style={{ background: course.accent }}>{course.image}</div><div className="min-w-0 flex-1"><h3 className="truncate font-display text-lg font-bold">{course.title}</h3><p className="mt-1 text-xs text-muted-foreground">{course.unitCode} · {course.resourceCount} resources · {formatKES(course.price)}</p></div><button onClick={() => edit(course)} data-testid={`button-edit-course-${course.id}`} className="grid h-9 w-9 place-items-center rounded-lg text-muted-foreground transition-colors hover:bg-muted hover:text-primary"><Pencil className="h-4 w-4" /></button><button onClick={() => { setSelected(course); setShowResourceForm(true); }} data-testid={`button-add-resource-${course.id}`} className="hidden items-center gap-1.5 rounded-lg bg-primary px-3 py-2 text-xs font-bold text-primary-foreground sm:inline-flex"><Plus className="h-3.5 w-3.5" /> Resource</button></div>)}</div></section><aside><div className="rounded-2xl bg-primary p-6 text-primary-foreground"><p className="font-mono text-[10px] uppercase tracking-[.18em] text-secondary">Publishing note</p><h2 className="mt-4 font-display text-2xl font-bold">Make every file earn its place.</h2><p className="mt-3 text-sm leading-6 text-primary-foreground/65">Use a clear title, a useful description, and the right type so learners can find what they need at the right moment.</p><div className="mt-7 flex flex-col gap-3 text-sm text-primary-foreground/75"><div className="flex gap-3"><Check className="h-4 w-4 shrink-0 text-secondary" /> Add the lesson outcome to descriptions</div><div className="flex gap-3"><Check className="h-4 w-4 shrink-0 text-secondary" /> Keep video titles specific</div><div className="flex gap-3"><Check className="h-4 w-4 shrink-0 text-secondary" /> Label past papers by sitting</div></div></div></aside></div>{showCourseForm && <Modal title={selected ? 'Edit course' : 'Create a course'} onClose={() => setShowCourseForm(false)}><form onSubmit={saveCourse} className="grid gap-4"><TextField label="Course title" value={courseForm.title} onChange={(value) => setCourseForm({ ...courseForm, title: value })} testId="input-course-title" required /><div className="grid gap-4 sm:grid-cols-2"><TextField label="Unit code" value={courseForm.unitCode} onChange={(value) => setCourseForm({ ...courseForm, unitCode: value })} testId="input-course-code" required /><TextField label="Price (KES)" type="number" value={courseForm.price} onChange={(value) => setCourseForm({ ...courseForm, price: value })} testId="input-course-price" required /></div><div className="grid gap-4 sm:grid-cols-2"><TextField label="Duration" value={courseForm.duration} onChange={(value) => setCourseForm({ ...courseForm, duration: value })} testId="input-course-duration" required /><label className="grid gap-2 text-sm font-semibold">Level<select value={courseForm.level} onChange={(event) => setCourseForm({ ...courseForm, level: event.target.value })} data-testid="select-course-level" className="h-11 rounded-lg border border-border bg-background px-3 font-normal outline-none focus:border-accent"><option value="foundation">Foundation</option><option value="intermediate">Intermediate</option><option value="advanced">Advanced</option></select></label></div><TextAreaField label="Description" value={courseForm.description} onChange={(value) => setCourseForm({ ...courseForm, description: value })} testId="input-course-description" required /><button disabled={createCourse.isPending || updateCourse.isPending} data-testid="button-save-course" className="mt-2 flex h-12 items-center justify-center gap-2 rounded-lg bg-primary font-bold text-primary-foreground disabled:opacity-60">{createCourse.isPending || updateCourse.isPending ? <LoaderCircle className="h-4 w-4 animate-spin" /> : <Check className="h-4 w-4" />} Save course</button></form></Modal>}{showResourceForm && <Modal title={`Add resource${selected ? ` · ${selected.title}` : ''}`} onClose={() => setShowResourceForm(false)}><form onSubmit={saveResource} className="grid gap-4"><TextField label="Resource title" value={resourceForm.title} onChange={(value) => setResourceForm({ ...resourceForm, title: value })} testId="input-resource-title" required /><label className="grid gap-2 text-sm font-semibold">Type<select value={resourceForm.type} onChange={(event) => setResourceForm({ ...resourceForm, type: event.target.value })} data-testid="select-resource-type" className="h-11 rounded-lg border border-border bg-background px-3 font-normal outline-none focus:border-accent"><option value="video">Video tutorial</option><option value="notes">Notes</option><option value="past-paper">Past paper</option><option value="quiz">Quiz</option></select></label><TextAreaField label="Description" value={resourceForm.description} onChange={(value) => setResourceForm({ ...resourceForm, description: value })} testId="input-resource-description" required /><div className="grid gap-4 sm:grid-cols-2"><TextField label="Duration" value={resourceForm.duration} onChange={(value) => setResourceForm({ ...resourceForm, duration: value })} testId="input-resource-duration" /><TextField label="File size" value={resourceForm.size} onChange={(value) => setResourceForm({ ...resourceForm, size: value })} testId="input-resource-size" /></div><button disabled={createResource.isPending || !selected} data-testid="button-save-resource" className="mt-2 flex h-12 items-center justify-center gap-2 rounded-lg bg-primary font-bold text-primary-foreground disabled:opacity-60">{createResource.isPending ? <LoaderCircle className="h-4 w-4 animate-spin" /> : <Plus className="h-4 w-4" />} Publish resource</button></form></Modal>}</main></AppShell>;
}

function TextField({ label, value, onChange, testId, type = 'text', required = false }: { label: string; value: string; onChange: (value: string) => void; testId: string; type?: string; required?: boolean }) {
  return <label className="grid gap-2 text-sm font-semibold">{label}<input required={required} type={type} value={value} onChange={(event) => onChange(event.target.value)} data-testid={testId} className="h-11 rounded-lg border border-border bg-background px-3 font-normal outline-none focus:border-accent focus:ring-2 focus:ring-accent/15" /></label>;
}
function TextAreaField({ label, value, onChange, testId, required = false }: { label: string; value: string; onChange: (value: string) => void; testId: string; required?: boolean }) {
  return <label className="grid gap-2 text-sm font-semibold">{label}<textarea required={required} value={value} onChange={(event) => onChange(event.target.value)} data-testid={testId} rows={4} className="rounded-lg border border-border bg-background px-3 py-3 font-normal outline-none focus:border-accent focus:ring-2 focus:ring-accent/15" /></label>;
}
function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: ReactNode }) {
  return <div className="fixed inset-0 z-50 grid place-items-center bg-primary/45 p-5 backdrop-blur-sm"><div className="max-h-[90dvh] w-full max-w-lg overflow-y-auto rounded-2xl border border-border bg-card p-6 shadow-2xl sm:p-8"><div className="flex items-center justify-between"><h2 className="font-display text-2xl font-bold">{title}</h2><button onClick={onClose} data-testid="button-close-modal" className="rounded-lg p-2 text-muted-foreground hover:bg-muted hover:text-primary"><X className="h-5 w-5" /></button></div><div className="mt-6">{children}</div></div></div>;
}

function ContactPage() {
  useSeo('Contact support', 'Get help with KASNEB Learning Hub courses, payments, and study access.');
  const submitContact = useSubmitContact();
  const [sent, setSent] = useState(false);
  const [form, setForm] = useState({ name: '', email: '', subject: '', message: '' });
  const submit = (event: FormEvent) => { event.preventDefault(); submitContact.mutate({ data: form }, { onSuccess: () => setSent(true), onError: () => setSent(true) }); };
  return <AppShell><main className="mx-auto max-w-7xl px-5 py-14 lg:px-8 lg:py-20"><div className="grid gap-12 lg:grid-cols-[.8fr_1.2fr]"><div><p className="font-mono text-[11px] uppercase tracking-[.2em] text-accent">Need a hand?</p><h1 className="mt-3 font-display text-5xl font-extrabold tracking-tight sm:text-7xl">Ask the<br /><span className="text-accent">study desk.</span></h1><p className="mt-6 max-w-md text-base leading-7 text-muted-foreground">Course access, M-Pesa payments, unit choices, or just a stuck question. Send a note and our team will get back to you.</p><div className="mt-10 flex flex-col gap-5"><div className="flex gap-4"><span className="grid h-10 w-10 place-items-center rounded-xl bg-secondary/30 text-accent"><Mail className="h-5 w-5" /></span><div><p className="text-sm font-bold">Email the desk</p><p className="mt-1 text-sm text-muted-foreground">hello@kasneblearning.co.ke</p></div></div><div className="flex gap-4"><span className="grid h-10 w-10 place-items-center rounded-xl bg-secondary/30 text-accent"><Clock3 className="h-5 w-5" /></span><div><p className="text-sm font-bold">Response window</p><p className="mt-1 text-sm text-muted-foreground">Monday to Friday · 8am–5pm EAT</p></div></div></div></div><div className="rounded-2xl border border-border bg-card p-6 sm:p-9">{sent ? <div className="flex min-h-[360px] flex-col items-center justify-center text-center"><div className="grid h-16 w-16 place-items-center rounded-full bg-secondary text-primary"><Check className="h-8 w-8" /></div><h2 className="mt-6 font-display text-3xl font-bold">Message received.</h2><p className="mt-3 max-w-sm text-sm leading-6 text-muted-foreground">The study desk has your note. We’ll reply to {form.email || 'your inbox'} soon.</p><button onClick={() => { setSent(false); setForm({ name: '', email: '', subject: '', message: '' }); }} data-testid="button-send-another" className="mt-7 text-sm font-bold text-accent hover:text-primary">Send another message</button></div> : <form onSubmit={submit} className="grid gap-5"><div className="grid gap-5 sm:grid-cols-2"><TextField label="Your name" value={form.name} onChange={(value) => setForm({ ...form, name: value })} testId="input-contact-name" required /><TextField label="Email address" type="email" value={form.email} onChange={(value) => setForm({ ...form, email: value })} testId="input-contact-email" required /></div><TextField label="Subject" value={form.subject} onChange={(value) => setForm({ ...form, subject: value })} testId="input-contact-subject" required /><TextAreaField label="How can we help?" value={form.message} onChange={(value) => setForm({ ...form, message: value })} testId="input-contact-message" required /><button disabled={submitContact.isPending} data-testid="button-submit-contact" className="flex h-12 items-center justify-center gap-2 rounded-lg bg-primary font-bold text-primary-foreground disabled:opacity-60">{submitContact.isPending ? <LoaderCircle className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />} Send to the desk</button></form>}</div></div></main></AppShell>;
}

function LoginPage() {
  useSeo('Sign in', 'Sign in to your KASNEB Learning Hub study room.');
  const health = useHealthSafe();
  return <div className="noise min-h-[100dvh] bg-primary text-primary-foreground"><div className="mx-auto grid min-h-[100dvh] max-w-7xl lg:grid-cols-2"><div className="flex flex-col justify-between p-6 sm:p-10 lg:p-14"><Logo inverse /><div className="hidden max-w-lg lg:block"><p className="font-mono text-[11px] uppercase tracking-[.2em] text-secondary">The focused route to exam day</p><h1 className="mt-5 font-display text-6xl font-extrabold leading-[.95] tracking-tight">Your next<br /><span className="text-secondary">mark starts here.</span></h1><p className="mt-6 max-w-md text-base leading-7 text-primary-foreground/60">Pick up where you left off, keep your streak, and stay close to the paper that matters.</p></div><p className="text-xs text-primary-foreground/45">© 2025 KASNEB Learning Hub · Nairobi</p></div><div className="flex items-center bg-background p-6 text-foreground sm:p-10 lg:p-14"><div className="w-full max-w-md"><Link href="/" data-testid="link-login-home" className="mb-12 inline-flex items-center gap-2 text-sm font-semibold text-muted-foreground hover:text-accent"><ArrowRight className="h-4 w-4 rotate-180" /> Back to home</Link><p className="font-mono text-[11px] uppercase tracking-[.2em] text-accent">Study room access</p><h2 className="mt-3 font-display text-4xl font-extrabold">Welcome back.</h2><p className="mt-3 text-sm leading-6 text-muted-foreground">Sign-in is ready for integration with your preferred identity provider.</p><div className="mt-8 rounded-2xl border border-secondary/40 bg-secondary/20 p-5"><div className="flex gap-3"><ShieldCheck className="h-5 w-5 shrink-0 text-accent" /><div><p className="text-sm font-bold">Integration-ready screen</p><p className="mt-1 text-xs leading-5 text-muted-foreground">Authentication is not connected yet. Your course catalog and checkout are available to explore without an account.</p></div></div></div><button disabled data-testid="button-sign-in" className="mt-7 flex h-13 w-full items-center justify-center gap-2 rounded-lg bg-primary px-4 font-bold text-primary-foreground opacity-60"><LogIn className="h-4 w-4" /> Sign in with your account</button><div className="mt-7 flex items-center gap-3 text-xs text-muted-foreground"><span className={`h-2 w-2 rounded-full ${health ? 'bg-secondary' : 'bg-accent'}`} /> Platform services {health ? 'online' : 'available for preview'}</div><p className="mt-12 text-center text-xs text-muted-foreground">New here? <Link href="/catalog" data-testid="link-login-catalog" className="font-bold text-accent hover:text-primary">Browse the catalog</Link></p></div></div></div></div>;
}

function useHealthSafe() {
  const healthQuery = useHealthCheck({ query: { queryKey: ['/api/healthz'] } });
  return Boolean(healthQuery.data?.status);
}

function EmptyState({ title, copy, action, onAction }: { title: string; copy: string; action: string; onAction: () => void }) {
  return <div className="my-10 rounded-2xl border border-dashed border-border bg-card p-10 text-center"><div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-secondary/25 text-accent"><BookOpen className="h-6 w-6" /></div><h2 className="mt-5 font-display text-2xl font-bold">{title}</h2><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-muted-foreground">{copy}</p><button onClick={onAction} data-testid="button-empty-action" className="mt-6 rounded-lg bg-primary px-4 py-3 text-sm font-bold text-primary-foreground">{action}</button></div>;
}

function NotFound() {
  useSeo('Page not found', 'This page is not on the KASNEB Learning Hub route.');
  return <AppShell><main className="mx-auto flex min-h-[65vh] max-w-3xl flex-col items-center justify-center px-5 py-20 text-center"><span className="font-mono text-7xl font-medium text-secondary">404</span><h1 className="mt-5 font-display text-4xl font-extrabold">This page missed the sitting.</h1><p className="mt-4 max-w-md text-sm leading-6 text-muted-foreground">The page you’re looking for has moved, or it never made it into the study plan.</p><Link href="/catalog" data-testid="link-404-catalog" className="mt-8 inline-flex items-center gap-2 rounded-lg bg-primary px-5 py-3 text-sm font-bold text-primary-foreground">Back to catalog <ArrowRight className="h-4 w-4" /></Link></main></AppShell>;
}

function Router() {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}><Switch>
    <Route path="/" component={Home} />
    <Route path="/catalog" component={Catalog} />
    <Route path="/courses/:courseId" component={CourseDetailPage} />
    <Route path="/library" component={LibraryPage} />
    <Route path="/library/courses/:courseId" component={LibraryCoursePage} />
    <Route path="/library/courses/:courseId/units/:unitId" component={LibraryUnitPage} />
    <Route path="/dashboard" component={DashboardPage} />
    <Route path="/checkout/:courseId" component={CheckoutPage} />
    <Route path="/admin/login" component={AdminLoginPage} />
    <Route path="/admin/accept-invite" component={AdminAcceptInvitePage} />
    <Route path="/admin" component={() => <AdminGuard><AdminOverviewPage /></AdminGuard>} />
    <Route path="/admin/courses" component={() => <AdminGuard><AdminLibraryPage /></AdminGuard>} />
    <Route path="/admin/students" component={() => <AdminGuard><AdminStudentsPage /></AdminGuard>} />
    <Route path="/admin/payments" component={() => <AdminGuard><AdminPaymentsPage /></AdminGuard>} />
    <Route path="/admin/support" component={() => <AdminGuard><AdminSupportPage /></AdminGuard>} />
    <Route path="/admin/settings" component={() => <AdminGuard><AdminSettingsPage /></AdminGuard>} />
    <Route path="/admin/team" component={() => <AdminGuard><AdminTeamPage /></AdminGuard>} />
    <Route path="/contact" component={ContactPage} />
    <Route path="/login" component={LoginPage} />
    <Route component={NotFound} />
  </Switch></ErrorBoundary>;
}

function App() {
  return <QueryClientProvider client={queryClient}><AdminAuthProvider><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></AdminAuthProvider></QueryClientProvider>;
}

export default App;